<?php
include 'includes/init.php';require_role(['Admin','Manager']);$message=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$basic=(float)($_POST['basic_salary']??0);$allowance=(float)($_POST['allowance']??0);$deduction=(float)($_POST['deduction']??0);$net=$basic+$allowance-$deduction;$bankId=(int)($_POST['bank_id']??0);if($net<=0||!$bankId||empty($_POST['employee_name']))throw new RuntimeException('Payroll information is invalid.');$conn->beginTransaction();$b=$conn->prepare('SELECT balance FROM banks WHERE id=? FOR UPDATE');$b->execute([$bankId]);if((float)$b->fetchColumn()<$net)throw new RuntimeException('Insufficient bank balance.');$no='PAY-'.date('Ym').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$conn->prepare('INSERT INTO payroll(payroll_no,trainer_id,employee_name,period_start,period_end,basic_salary,allowance,deduction,net_pay,bank_id,payment_date,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$no,$_POST['trainer_id']?:null,trim($_POST['employee_name']),$_POST['period_start'],$_POST['period_end'],$basic,$allowance,$deduction,$net,$bankId,$_POST['payment_date'],$_SESSION['userId']]);$id=(int)$conn->lastInsertId();$conn->prepare('UPDATE banks SET balance=balance-? WHERE id=?')->execute([$net,$bankId]);post_journal($_POST['payment_date'],'Payroll '.$no,'payroll',$id,[['account_id'=>account_id('5100'),'debit'=>$net],['account_id'=>account_id('1000'),'credit'=>$net]]);audit('create','payroll',$id,['net'=>$net]);$conn->commit();$message=['Payroll paid successfully.','success'];}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$message=[$e->getMessage(),'danger'];}}
$trainers=$conn->query("SELECT id,FullName FROM trainers WHERE Status='Active' ORDER BY FullName")->fetchAll();$banks=$conn->query('SELECT id,name,balance FROM banks ORDER BY name')->fetchAll();$rows=$conn->query('SELECT p.*,b.name bank_name FROM payroll p JOIN banks b ON b.id=p.bank_id ORDER BY p.payment_date DESC,p.id DESC')->fetchAll();
?>
<div class="container-fluid"><div class="d-flex justify-content-between mb-4"><h3>Payroll</h3><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#payrollModal">Process Payroll</button></div><div class="alerts"><?php if($message)showMessage($message);?></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>No.</th><th>Employee</th><th>Period</th><th>Paid From</th><th>Date</th><th class="text-end">Net Pay</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=escape($r['payroll_no'])?></td><td><?=escape($r['employee_name'])?></td><td><?=escape($r['period_start'].' – '.$r['period_end'])?></td><td><?=escape($r['bank_name'])?></td><td><?=escape($r['payment_date'])?></td><td class="text-end fw-semibold"><?=money($r['net_pay'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center py-4">No payroll records.</td></tr><?php endif;?></tbody></table></div></div></div>
<div class="modal fade" id="payrollModal"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h5>Process Payroll</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><div class="mb-3"><label class="form-label">Trainer (optional)</label><select name="trainer_id" id="trainerPayroll" class="form-select"><option value="">Other employee</option><?php foreach($trainers as $t):?><option value="<?=$t['id']?>" data-name="<?=escape($t['FullName'])?>"><?=escape($t['FullName'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Employee Name</label><input name="employee_name" id="employeeName" class="form-control" required></div><div class="row"><div class="col-6 mb-3"><label class="form-label">Period Start</label><input type="date" name="period_start" value="<?=date('Y-m-01')?>" class="form-control" required></div><div class="col-6 mb-3"><label class="form-label">Period End</label><input type="date" name="period_end" value="<?=date('Y-m-t')?>" class="form-control" required></div></div><div class="row"><?php foreach(['basic_salary'=>'Basic Salary','allowance'=>'Allowance','deduction'=>'Deduction'] as $n=>$l):?><div class="col-4 mb-3"><label class="form-label"><?=$l?></label><input type="number" min="0" step="0.01" name="<?=$n?>" value="0" class="form-control" required></div><?php endforeach;?></div><div class="mb-3"><label class="form-label">Bank</label><select name="bank_id" class="form-select" required><?php foreach($banks as $b):?><option value="<?=$b['id']?>"><?=escape($b['name'])?> (<?=money($b['balance'])?>)</option><?php endforeach;?></select></div><div><label class="form-label">Payment Date</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div></div><div class="modal-footer"><button class="btn btn-primary">Pay & Post Payroll</button></div></form></div></div><script>document.getElementById('trainerPayroll').addEventListener('change',function(){const o=this.options[this.selectedIndex];if(o.dataset.name)document.getElementById('employeeName').value=o.dataset.name;});</script>
<?php include 'includes/footer.php';?>
